public static class CustomRoleManager {public static Dictionary<byte,RoleBase> AllActiveRoles=new();public static Dictionary<CustomRoles,SimpleRoleInfo> AllRolesInfo=new();public static int Forced;public static bool Reenter,Throw;public static SimpleRoleInfo GetRoleInfo(this CustomRoles r)=>AllRolesInfo.GetValueOrDefault(r);public static bool OnCheckMurder(PlayerControl k,PlayerControl t,PlayerControl ak,PlayerControl at,bool force,bool dont,int power,CustomDeathReason reason){if(!force||!dont||power!=99||reason!=CustomDeathReason.Misfire||k!=t||k!=ak||k!=at)throw new Exception("unsafe forced path");Forced++;if(Throw)throw new InvalidOperationException("synthetic self-murder failure");if(Reenter)(k.GetRoleClass() as Interfaces.IKiller)?.OnCheckMurderAsKiller(new(k,k));t.Data.IsDead=true;(k.GetRoleClass() as Interfaces.IKiller)?.OnMurderPlayerAsKiller(new(k,t));return true;}}
